<?php $sessionBase='/volunteer/'.$session['id']; $state=vs_state($session); $current=vs_current($session); ?>
<div class="volunteer-start"><h1>Volunteer session</h1><div class="session-meta"><p><strong><?=e(max(0,(int)$session['assignment_limit']-(int)$session['assignments_used']))?></strong> assignments remaining</p><p><strong><?=e(max(0,(int)ceil((strtotime($session['expires_at'].' UTC')-vs_now())/60)))?></strong> min remaining</p><p>Session ends <time datetime="<?=e(str_replace(' ','T',$session['expires_at']).'Z')?>"><?=e($session['expires_at'])?> UTC</time></p></div><p class="session-state"><?=e(vs_state_label($state))?></p>
<?php if($error): ?><p class="warning" role="alert"><?=e($error)?></p><?php endif ?>
<div class="actions primary-actions" data-session-actions>
<?php if($current && in_array($state,['active','limit_reached'],true)): ?><form method="post"><?=csrf()?><input type="hidden" name="assignment_id" value="<?=e($current['id'])?>"><button name="operation" value="handoff">Copy task handoff</button></form><a class="button secondary" href="<?=e($sessionBase)?>/assignments/<?=e($current['id'])?>">Open result form</a><form method="post"><?=csrf()?><input type="hidden" name="assignment_id" value="<?=e($current['id'])?>"><button class="secondary" name="operation" value="renew">Renew reservation</button><button class="secondary" name="operation" value="release">Release task</button></form><?php elseif($state==='active'): ?><form method="post"><?=csrf()?><button name="operation" value="claim">Pick up next task</button></form><?php endif ?>
<?php if(!$session['stopped_at']): ?><form method="post"><?=csrf()?><button class="secondary" name="operation" value="stop">Stop session</button></form><?php endif ?></div>
<p class="fine"><?=e(vs_scope_label($session))?>. One active task. Recopying, repair and renewal consume no assignment. Releasing does not restore an assignment.</p>
<?php if($current): $item=vs_public_assignment($session,$current); ?><section class="session-activity"><h2>Current assignment</h2><?php if($item['available']): ?><p><a href="<?=e($item['task_url'])?>"><?=e($item['title'])?></a></p><p><?=e($item['reservation_text'])?></p><?php if($item['reacquire'] && in_array($state,['active','limit_reached'],true)): ?><form method="post"><?=csrf()?><input type="hidden" name="assignment_id" value="<?=e($current['id'])?>"><button name="operation" value="reacquire">Reacquire this assignment</button></form><p class="fine">Reacquisition checks current eligibility and preserves the original packet identifiers. Another holder cannot be displaced.</p><?php endif ?><?php else: ?><p>This research is no longer available. Its content and links are hidden.</p><?php endif ?></section><?php endif ?>
<section class="session-activity"><h2>Activity and recorded outcomes</h2><ol class="session-history"><?php foreach(all('SELECT * FROM volunteer_assignments WHERE session_id=? ORDER BY created_at,id',[$session['id']]) as $assignment): $item=vs_public_assignment($session,$assignment); ?><li><time><?=e($assignment['created_at'])?> UTC</time> · <strong><?=e($item['outcome'])?></strong><?php if($item['available']): ?><p><?=e($item['title'])?><?php if($item['receipt_url']): ?> · <a href="<?=e($item['receipt_url'])?>">Read recorded receipt</a><?php endif ?></p><?php else: ?><p>Research unavailable; content and links hidden.</p><?php endif ?></li><?php endforeach ?></ol><?php if(!(int)$session['assignments_used']): ?><p>No assignments picked up yet.</p><?php endif ?></section>
<p class="fine">Stop blocks new claims, renewal and submissions here and releases your held task. Also stop the external AI tool; this site cannot halt its execution. Existing receipts remain available after Stop or expiry.</p><?php if(is_file(ROOT.'/views/volunteer-guide-link.php')) include __DIR__.'/volunteer-guide-link.php'; ?></div>
